def _run_decode_ebnf(
    self,
    ebnf,
    expected_patterns,
    prompt,
    return_logprob=False,
    top_logprobs_num=0,
    n=1,
):
    response = requests.post(
        self.base_url + "/generate",
        json={
            "text": prompt,
            "sampling_params": {
                "temperature": 0 if n == 1 else 0.5,
                "max_new_tokens": 128,
                "n": n,
                "ebnf": ebnf,
            },
            "stream": False,
            "return_logprob": return_logprob,
            "top_logprobs_num": top_logprobs_num,
            "logprob_start_len": 0,
        },
    )

    ret = response.json()
    print(json.dumps(ret, indent=2))
    print("=" * 100)

    if not isinstance(ret, list):
        self.fail(f"Expected response to be a list, but got {type(ret)}")

    for item in ret:
        text = item.get("text", "").strip()
        if not text:
            self.fail("Generated text is empty.")

        match = False
        for pattern in expected_patterns:
            if self.regex_match(text, pattern):
                match = True
                break
        if not match:
            self.fail(f"Text '{text}' does not match any of the allowed patterns.")

def regex_match(self, text, pattern):
    import re

    return re.match(pattern, text) is not None

